INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2271IBO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $MNP$, $Q$ is the midpoint of $\\overline{MN}$ and $R$ is the midpoint of $\\overline{MP}$. The midsegment $\\overline{QR}$ is parallel to $\\overline{NP}$. If $MN = 26$, $MP = 34$, and $NP = 38$, what is the perimeter of triangle $MQR$?', NULL, $lyceon_json$[{"key":"A","text":"$30$"},{"key":"B","text":"$49$"},{"key":"C","text":"$68$"},{"key":"D","text":"$98$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since $Q$ and $R$ are midpoints, $MQ = \\frac{26}{2} = 13$ and $MR = \\frac{34}{2} = 17$. By the triangle midsegment theorem, $QR = \\frac{NP}{2} = \\frac{38}{2} = 19$. The perimeter of triangle $MQR$ is $13 + 17 + 19 = 49$. The value $30$ comes from computing only $MQ + MR = 13 + 17 = 30$ and omitting the midsegment $QR$. The value $68$ results from using the full length $NP = 38$ instead of its half for $QR$, giving $13 + 17 + 38 = 68$. The value $98$ is the perimeter of the original triangle $MNP$ ($26 + 34 + 38 = 98$), confusing the two triangles.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22Y38LN', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $f$ is defined for all real numbers such that $f(x + 3) = f(x) + 21$ for every value of $x$. If $f(2) = -8$, what is the value of $f(11)$?', NULL, $lyceon_json$[{"key":"A","text":"$55$"},{"key":"B","text":"$13$"},{"key":"C","text":"$63$"},{"key":"D","text":"$-71$"}]$lyceon_json$::jsonb, 'A', NULL, E'The condition $f(x + 3) = f(x) + 21$ means the function increases by $21$ for every increase of $3$ in $x$, so the rate of change is $\\frac{21}{3} = 7$. From $x = 2$ to $x = 11$, the change in $x$ is $9$, so $f(11) = f(2) + 7 \\cdot 9 = -8 + 63 = 55$. Alternatively, applying the rule step by step: $f(5) = f(2) + 21 = 13$, $f(8) = f(5) + 21 = 34$, $f(11) = f(8) + 21 = 55$. The value $13$ results from applying the rule only once ($f(5) = -8 + 21 = 13$) and stopping too early. The value $63$ comes from computing the total change $7 \\times 9 = 63$ but not adding it to $f(2) = -8$. The value $-71$ results from subtracting $63$ from $-8$ instead of adding it, reversing the direction of the change.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM251KNVQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'If $y = 2x + 1$ and $y = x^2 - 3x + 7$, what is the sum of all $x$-values that satisfy both equations simultaneously?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$5$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the expressions equal: $2x + 1 = x^2 - 3x + 7$, which rearranges to $x^2 - 5x + 6 = 0$. Factoring gives $(x - 2)(x - 3) = 0$, so $x = 2$ or $x = 3$. The sum is $2 + 3 = 5$. Choosing $6$ confuses the sum with the product of the roots. Choosing $-5$ results from a sign error when applying Vieta''s formulas. Choosing $3$ picks only one of the two solutions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25Z5RLS', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = -4(x - 1)^2 + 9$, and the function $g$ is defined by $g(x) = f(x + 6) - 3$. What is the $x$-coordinate of the vertex of $y = g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$5$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The vertex of $f(x) = -4(x - 1)^2 + 9$ is at $(1, 9)$. The transformation $g(x) = f(x + 6) - 3$ replaces $x$ with $x + 6$, which shifts the graph $6$ units to the left, and subtracts $3$, which shifts it down $3$ units. The new vertex $x$-coordinate is $1 - 6 = -5$. To verify: $g(x) = -4((x + 6) - 1)^2 + 9 - 3 = -4(x + 5)^2 + 6$, so the vertex is at $(-5, 6)$. The value $7$ comes from adding $6$ to $1$ instead of subtracting, treating $x + 6$ as a rightward shift (sign error on the horizontal translation direction). The value $5$ comes from computing $6 - 1$ instead of $1 - 6$ (sign error in the subtraction order). The value $-7$ comes from subtracting $6$ from $1$ correctly to get $-5$ but then also subtracting the vertical shift from the $x$-coordinate, arriving at $-5 - 2 = -7$ (concept gap, mixing horizontal and vertical shifts).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26YNSUG', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $8x^2 + 20x$?', NULL, $lyceon_json$[{"key":"A","text":"$4x(2x + 5)$"},{"key":"B","text":"$2x(4x + 5)$"},{"key":"C","text":"$4x(2x + 20)$"},{"key":"D","text":"$8x(x + 20)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The greatest common factor of $8x^2$ and $20x$ is $4x$. Dividing each term by $4x$ gives $8x^2 \\div 4x = 2x$ and $20x \\div 4x = 5$, so $8x^2 + 20x = 4x(2x + 5)$. The expression $2x(4x + 5)$ expands to $8x^2 + 10x$, which differs because only $2x$ was factored out from the first term but the second term was divided by $4x$ instead of $2x$. The expression $4x(2x + 20)$ expands to $8x^2 + 80x$, resulting from failing to divide $20$ by $4$. The expression $8x(x + 20)$ expands to $8x^2 + 160x$, resulting from factoring out $8x$ but failing to divide the coefficient $20$ by $8$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26ZNWEE', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'What value of $x$ satisfies the equation $\\frac{5x + 1}{3} - \\frac{2x - 7}{6} = 9$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '45/8', ARRAY['45/8', '5.625'], E'The least common denominator is $6$. Multiply the first fraction by $\\frac{2}{2}$: $\\frac{2(5x + 1)}{6} - \\frac{2x - 7}{6} = 9$. Combine the numerators: $\\frac{10x + 2 - 2x + 7}{6} = 9$, which simplifies to $\\frac{8x + 9}{6} = 9$. Multiply both sides by $6$: $8x + 9 = 54$. Subtract $9$: $8x = 45$. Divide by $8$: $x = \\frac{45}{8}$. A common error is distributing the subtraction sign incorrectly into the second numerator, writing $-2x - 7$ instead of $-2x + 7$, which changes the combined numerator and leads to a different answer.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A733FS', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'When $\\frac{14x^4 - 21x^3 + 35x^2}{7x^2}$ is simplified, the result can be written as $2x^2 + bx + c$ for constants $b$ and $c$. What is the value of $c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Dividing each term by $7x^2$: $\\frac{14x^4}{7x^2} - \\frac{21x^3}{7x^2} + \\frac{35x^2}{7x^2} = 2x^2 - 3x + 5$. Comparing with $2x^2 + bx + c$ gives $b = -3$ and $c = 5$.', NULL, NULL, 'draft', 1, 65, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AQ9TP9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'A toy rocket is launched from a platform. Its height above the ground, in meters, is modeled by $h(t) = -3(t - 2)(t - 14)$, where $t$ is the time in seconds after launch, for $0 \\leq t \\leq 14$. What is the maximum height, in meters, the rocket reaches?', NULL, $lyceon_json$[{"key":"A","text":"$96$"},{"key":"B","text":"$108$"},{"key":"C","text":"$48$"},{"key":"D","text":"$36$"}]$lyceon_json$::jsonb, 'B', NULL, E'The zeros of $h(t) = -3(t - 2)(t - 14)$ are at $t = 2$ and $t = 14$. The axis of symmetry is at $t = \\frac{2 + 14}{2} = 8$. The maximum height is $h(8) = -3(8 - 2)(8 - 14) = -3(6)(-6) = -3(-36) = 108$ meters. The value $96$ comes from computing $-3(4)(-8) = 96$ by using $t = 6$ or another incorrect midpoint (arithmetic slip in finding the axis of symmetry). The value $48$ comes from computing $(6)(8) = 48$, dropping the leading coefficient of $-3$ entirely (concept gap about the role of the coefficient in determining height). The value $36$ comes from computing $(6)(6) = 36$ but omitting the factor of $-3$ (partial reasoning, finding only the product of the factor magnitudes without applying the coefficient).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BRSVRQ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = -7x + 53$. What is the value of $g(6)$?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$-11$"},{"key":"C","text":"$95$"},{"key":"D","text":"$-42$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substitute $x = 6$: $g(6) = -7(6) + 53 = -42 + 53 = 11$. The value $-11$ reverses the sign of the correct result. The value $95$ comes from computing $7(6) + 53 = 42 + 53 = 95$, ignoring the negative coefficient on $x$. The value $-42$ results from computing $-7(6) = -42$ but stopping there without adding $53$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CWQ100', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $p$ satisfies $p(2) = 17$ and $p(7) = 47$. What is the rate of change of $p$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$30$"},{"key":"D","text":"$\\frac{1}{6}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate of change is $\\frac{p(7) - p(2)}{7 - 2} = \\frac{47 - 17}{5} = \\frac{30}{5} = 6$. The value $-6$ reverses the sign by computing $\\frac{17 - 47}{7 - 2}$ and taking the magnitude incorrectly, or by swapping the order of subtraction in only the numerator. The value $30$ represents only the change in function values ($47 - 17 = 30$) without dividing by the change in input, stopping one step short. The value $\\frac{1}{6}$ is the reciprocal of the correct rate, resulting from inverting the fraction $\\frac{\\Delta x}{\\Delta y}$ instead of $\\frac{\\Delta y}{\\Delta x}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DQZA5V', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'A biologist models a bacteria population with the function $p(t) = 250 \\cdot \\left(\\frac{1}{5}\\right)^t$, where $t$ is the number of days after treatment. What is $p(2)$?', NULL, $lyceon_json$[{"key":"A","text":"$50$"},{"key":"B","text":"$100$"},{"key":"C","text":"$10$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $t = 2$ gives $p(2) = 250 \\cdot \\left(\\frac{1}{5}\\right)^2 = 250 \\cdot \\frac{1}{25} = 10$. The value $50$ comes from computing $\\left(\\frac{1}{5}\\right)^1$ instead of $\\left(\\frac{1}{5}\\right)^2$, evaluating only one step of the decay (partial reasoning). The value $100$ comes from dividing $250$ by $2.5$ or confusing the decay factor with dividing by the exponent (concept gap about exponential decay). The value $25$ comes from computing $250 \\cdot \\frac{1}{5} \\cdot \\frac{1}{2}$ instead of $250 \\cdot \\frac{1}{5} \\cdot \\frac{1}{5}$ (arithmetic slip on the second factor).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EQCMSR', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 7x^2 + 3x - 19$. What is the value of $f(-3)$?', NULL, $lyceon_json$[{"key":"A","text":"$53$"},{"key":"B","text":"$35$"},{"key":"C","text":"$54$"},{"key":"D","text":"$-91$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = -3$ into $f(x) = 7x^2 + 3x - 19$ gives $f(-3) = 7(-3)^2 + 3(-3) - 19 = 7(9) - 9 - 19 = 63 - 9 - 19 = 35$. The value $53$ comes from computing $3(-3)$ as $+9$ instead of $-9$ (sign error on the linear term), giving $63 + 9 - 19 = 53$. The value $54$ comes from computing $63 - 9 = 54$ and stopping before subtracting the constant $19$ (partial reasoning). The value $-91$ comes from treating $(-3)^2$ as $-9$ instead of $+9$ (sign error on the squared term), giving $-63 - 9 - 19 = -91$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F0VBQQ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $f$ satisfies $f(-2) = 31$ and $f(6) = -9$. What is the value of $f(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$41$"},{"key":"C","text":"$31$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{-9 - 31}{6 - (-2)} = \\frac{-40}{8} = -5$. Using the point $(-2, 31)$ in point-slope form: $y - 31 = -5(x + 2)$, which gives $y = -5x - 10 + 31 = -5x + 21$. Therefore $f(0) = 21$. The value $41$ results from a sign error when computing the intercept: adding $10$ to $31$ instead of subtracting ($31 + 10 = 41$), which occurs when the slope is incorrectly taken as $+5$. The value $31$ comes from assuming $f(0) = f(-2)$ without computing the actual $y$-intercept. The value $11$ results from averaging the two given $y$-values ($\\frac{31 + (-9)}{2} = 11$), which gives the midpoint of the outputs rather than the value at $x = 0$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F2FZOX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = -5(x - 4)^2 + 17$. Which of the following describes the range of $f$?', NULL, $lyceon_json$[{"key":"A","text":"$f(x) \\leq 17$"},{"key":"B","text":"$f(x) \\geq 17$"},{"key":"C","text":"$f(x) \\leq -5$"},{"key":"D","text":"All real numbers"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $f(x) = -5(x - 4)^2 + 17$ has a negative leading coefficient ($-5$), the parabola opens downward. The vertex is at $(4, 17)$, which is the maximum point. Therefore the range is all values $f(x) \\leq 17$. The claim $f(x) \\geq 17$ reverses the direction of the inequality, treating the vertex as a minimum instead of a maximum (sign error on the direction the parabola opens). The claim $f(x) \\leq -5$ confuses the leading coefficient with the vertex value (concept gap about what determines the range). The claim that the range is all real numbers applies to odd-degree polynomials, not quadratics (concept gap about quadratic range).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FI5W0Q', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A textile factory produces 258 meters of fabric using 43 kilograms of raw cotton. A second factory produces 372 meters of fabric using 62 kilograms of a different raw cotton blend. What is the positive difference, in meters per kilogram, between the two factories'' fabric yields?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$0.6$"},{"key":"C","text":"$6$"},{"key":"D","text":"$114$"}]$lyceon_json$::jsonb, 'A', NULL, E'The first factory''s yield is $\\frac{258}{43} = 6$ meters per kilogram. The second factory''s yield is $\\frac{372}{62} = 6$ meters per kilogram. The positive difference is $6 - 6 = 0$ meters per kilogram. The value $0.6$ results from an arithmetic slip such as miscalculating one of the divisions. The value $6$ comes from mistakenly reporting one factory''s rate instead of the difference between them. The value $114$ results from subtracting the meters ($372 - 258 = 114$) without converting to rates.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FNFYT2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A circle has a radius of $10$. What is the area of a sector of this circle with a central angle of $108°$?', NULL, $lyceon_json$[{"key":"A","text":"$6\\pi$"},{"key":"B","text":"$30\\pi$"},{"key":"C","text":"$60\\pi$"},{"key":"D","text":"$100\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a sector is $\\frac{\\theta}{360} \\cdot \\pi r^2 = \\frac{108}{360} \\cdot \\pi(10)^2 = \\frac{3}{10} \\cdot 100\\pi = 30\\pi$. The value $6\\pi$ is the arc length of the sector, $\\frac{108}{360} \\cdot 2\\pi(10) = 6\\pi$, confusing arc length with sector area. The value $60\\pi$ results from dividing by $180$ instead of $360$: $\\frac{108}{180} \\cdot 100\\pi = \\frac{3}{5} \\cdot 100\\pi = 60\\pi$. The value $100\\pi$ is the area of the entire circle, ignoring the fractional portion determined by the central angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FPYLDO', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'Line $q$ passes through the points $(-3, 11)$ and $(5, -13)$. Which of the following is the equation of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$y = -3x + 2$"},{"key":"B","text":"$y = -3x - 2$"},{"key":"C","text":"$y = 3x + 2$"},{"key":"D","text":"$y = -\\frac{1}{3}x + 2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{-13 - 11}{5 - (-3)} = \\frac{-24}{8} = -3$. Using point-slope form with $(-3, 11)$: $y - 11 = -3(x + 3)$, which gives $y = -3x - 9 + 11 = -3x + 2$. Verification: at $x = 5$, $y = -15 + 2 = -13$. The equation $y = -3x - 2$ has the correct slope but the wrong sign on the intercept, resulting from a sign error when simplifying $-9 + 11$. The equation $y = 3x + 2$ negates the slope, producing a line that increases rather than decreases. The equation $y = -\\frac{1}{3}x + 2$ uses the reciprocal of the slope rather than the slope itself, reflecting a misunderstanding of the slope formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G5H79O', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'The equation $2x - 11y = 44$ represents a line in the $xy$-plane. What is the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2}{11}$"},{"key":"B","text":"$-\\frac{2}{11}$"},{"key":"C","text":"$\\frac{11}{2}$"},{"key":"D","text":"$-4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewrite in slope-intercept form: $-11y = -2x + 44$, so $y = \\frac{2}{11}x - 4$. The slope is $\\frac{2}{11}$. The value $-\\frac{2}{11}$ results from a sign error when dividing $-2x$ by $-11$, incorrectly keeping the negative. The value $\\frac{11}{2}$ confuses the slope with its reciprocal, swapping the coefficients of $x$ and $y$. The value $-4$ is the $y$-intercept, not the slope, and results from misreading the question.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GA60Z2', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A gym membership costs $\\$19$ per month plus a one-time registration fee of $\\$41$. A person has a budget of no more than $\\$193$. What is the maximum number of full months of membership the person can afford?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'The total cost for $m$ months is $41 + 19m$. Setting up the inequality $41 + 19m \\leq 193$ and subtracting 41 from both sides gives $19m \\leq 152$. Dividing both sides by 19 gives $m \\leq 8$. Since $m$ must be a whole number, the maximum number of full months is 8.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GYJKTT', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'grid_in', E'If $4(3x - 7) + x = 13x + m$ for all values of $x$, what is the value of $m$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-28', ARRAY['-28'], E'Expanding the left side: $12x - 28 + x = 13x - 28$. Since this must equal $13x + m$ for all $x$, comparing constant terms gives $m = -28$.', NULL, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HJW0HB', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A candle is $34$ centimeters tall when first lit. The function $h(t) = -\\frac{3}{4}t + 34$ models the height $h$, in centimeters, of the candle $t$ minutes after it is lit. Which of the following is the best interpretation of $-\\frac{3}{4}$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"The candle's height decreases by $\\frac{3}{4}$ centimeter each minute it burns"},{"key":"B","text":"The candle is $\\frac{3}{4}$ centimeter tall when it is first lit"},{"key":"C","text":"The candle burns for $\\frac{3}{4}$ of a minute before going out"},{"key":"D","text":"The candle's height increases by $\\frac{3}{4}$ centimeter each minute it burns"}]$lyceon_json$::jsonb, 'A', NULL, E'In the function $h(t) = -\\frac{3}{4}t + 34$, the coefficient $-\\frac{3}{4}$ multiplies the variable $t$, so it represents the rate of change: the height decreases by $\\frac{3}{4}$ centimeter for each additional minute. The initial height is represented by $34$, the constant term, not the coefficient. The interpretation that the candle burns for $\\frac{3}{4}$ of a minute confuses the rate of change with a duration. The interpretation that height increases by $\\frac{3}{4}$ centimeter ignores the negative sign, which indicates a decrease rather than an increase.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IDJXPV', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What values of $x$ satisfy $7x^2 = 343$?', NULL, $lyceon_json$[{"key":"A","text":"$7$ only"},{"key":"B","text":"$-7$ only"},{"key":"C","text":"$7$ and $-7$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'C', NULL, E'Dividing both sides by $7$ gives $x^2 = 49$, so $x = 7$ or $x = -7$. Choosing $7$ only or $-7$ only overlooks that both the positive and negative square roots satisfy the equation. Choosing $49$ results from dividing $343$ by $7$ but neglecting to take the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IL58Z1', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following describes all values of $x$ that satisfy $9x - 13 \\geq 59$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\geq 8$"},{"key":"B","text":"$x \\leq 8$"},{"key":"C","text":"$x \\geq 72$"},{"key":"D","text":"$x \\geq \\frac{59}{9}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding 13 to both sides gives $9x \\geq 72$, and dividing both sides by 9 gives $x \\geq 8$. The answer $x \\leq 8$ incorrectly reverses the inequality direction when dividing by a positive number. The answer $x \\geq 72$ results from adding 13 but forgetting to divide by 9. The answer $x \\geq \\frac{59}{9}$ results from dividing 59 by 9 without first adding 13 to both sides.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IVIOK1', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 + 11x + 18}{x^2 - 4} \\cdot \\frac{x^2 - 5x + 6}{x^2 + 6x - 27}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$\\frac{x + 2}{x - 2}$"},{"key":"C","text":"$\\frac{x - 2}{x - 9}$"},{"key":"D","text":"$\\frac{1}{x + 2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor each polynomial: $x^2 + 11x + 18 = (x + 2)(x + 9)$, $x^2 - 4 = (x + 2)(x - 2)$, $x^2 - 5x + 6 = (x - 2)(x - 3)$, and $x^2 + 6x - 27 = (x + 9)(x - 3)$. The product becomes $\\frac{(x + 2)(x + 9)}{(x + 2)(x - 2)} \\cdot \\frac{(x - 2)(x - 3)}{(x + 9)(x - 3)}$. Every factor in the numerator cancels with a matching factor in the denominator, yielding $1$. Choosing $\\frac{x + 2}{x - 2}$ results from only partially canceling the $(x + 9)$ and $(x - 3)$ factors. Choosing $\\frac{x - 2}{x - 9}$ reflects a factoring error in $x^2 + 6x - 27$. Choosing $\\frac{1}{x + 2}$ comes from an arithmetic slip during cancellation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J32R5W', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'Triangles $RST$ and $UVW$ are similar, with $\\overline{RS}$ corresponding to $\\overline{UV}$, $\\overline{ST}$ corresponding to $\\overline{VW}$, and $\\overline{RT}$ corresponding to $\\overline{UW}$. In triangle $RST$, $RS = 2x - 1$, $ST = 18$, and $RT = 12$. In triangle $UVW$, $UV = 35$, $VW = 42$, and $UW = 28$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$8$"},{"key":"C","text":"$15$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since the triangles are similar with the given correspondence, corresponding sides are proportional. Using $ST$ and $VW$: $\\frac{ST}{VW} = \\frac{18}{42} = \\frac{3}{7}$. Verify with $RT$ and $UW$: $\\frac{12}{28} = \\frac{3}{7}$. Applying this ratio to $RS$ and $UV$: $\\frac{2x - 1}{35} = \\frac{3}{7}$, so $2x - 1 = 15$, giving $2x = 16$ and $x = 8$. The value $7$ results from a sign error when solving $2x - 1 = 15$: subtracting $1$ from the right side instead of adding, yielding $2x = 14$ and $x = 7$. The value $15$ is the length of $RS$ itself ($2(8) - 1 = 15$); this error stops at the intermediate result instead of solving for $x$. The value $18$ results from assuming the triangles are congruent rather than similar, setting $2x - 1 = 35$ and solving $2x = 36$, $x = 18$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JP0GDJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A bag contains 11 red marbles, 7 blue marbles, and 5 green marbles. Two marbles are drawn at random without replacement. Given that the first marble drawn is blue, what is the probability that the second marble drawn is also blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{6}{22}$"},{"key":"B","text":"$\\frac{7}{23}$"},{"key":"C","text":"$\\frac{6}{23}$"},{"key":"D","text":"$\\frac{7}{22}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is $11 + 7 + 5 = 23$. Given that the first marble drawn is blue, 6 blue marbles remain out of $23 - 1 = 22$ total marbles. The probability is $\\frac{6}{22}$, which simplifies to $\\frac{3}{11}$. The value $\\frac{7}{23}$ treats the draw as if no marble was removed, using the original counts for both the numerator and denominator. The value $\\frac{6}{23}$ correctly reduces the number of blue marbles by one but fails to reduce the total from 23 to 22. The value $\\frac{7}{22}$ reduces the total by one but does not reduce the blue count, ignoring that the first drawn marble was blue.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K6QCR8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A retailer buys a shipment of 2,300 electronic components at $\\$1.70$ each. After testing, $12\\%$ of the components are found to be defective and are discarded. The retailer sells each working component at a price that yields a $35\\%$ profit on the total cost of the entire shipment (including the defective components). What is the selling price per working component, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$\\$2.30$"},{"key":"B","text":"$\\$2.61$"},{"key":"C","text":"$\\$2.40$"},{"key":"D","text":"$\\$2.20$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total cost of the shipment is $2300 \\times 1.70 = 3910$ dollars. A $35\\%$ profit requires total revenue of $3910 \\times 1.35 = 5278.50$ dollars. The number of defective components is $2300 \\times 0.12 = 276$, so there are $2300 - 276 = 2024$ working components. The selling price per working component is $\\frac{5278.50}{2024} \\approx 2.608$, which rounds to $\\$2.61$. The value $\\$2.30$ results from computing $1.70 \\times 1.35 = 2.295 \\approx 2.30$, applying the markup to the per-unit cost without accounting for the defective components reducing the number of sellable units. The value $\\$2.40$ comes from an incorrect setup such as dividing total revenue by 2200 instead of 2024. The value $\\$2.20$ results from an arithmetic error such as miscomputing the profit or the number of working components.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K788ZP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f(x) = 3x^2 + 18x + 31$ can be rewritten in the form $f(x) = 3(x + a)^2 + b$. What is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$58$"},{"key":"B","text":"$4$"},{"key":"C","text":"$31$"},{"key":"D","text":"$-4$"}]$lyceon_json$::jsonb, 'B', NULL, E'Completing the square: $f(x) = 3(x^2 + 6x) + 31 = 3(x^2 + 6x + 9 - 9) + 31 = 3(x + 3)^2 - 27 + 31 = 3(x + 3)^2 + 4$. So $b = 4$. The value $58$ comes from adding $27$ to $31$ instead of subtracting it (sign error when distributing the $3$ to the $-9$ term). The value $31$ comes from reading the original constant without completing the square (partial reasoning, stopping before the vertex form is finished). The value $-4$ comes from reversing the subtraction, computing $27 - 31$ instead of $31 - 27$ (arithmetic slip).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KCY7KV', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A bakery makes two types of pastries. Type P takes 7 minutes to prepare and Type Q takes 11 minutes. The baker has at most 154 minutes of preparation time and must make at least 6 pastries of Type P. If each Type P sells for $\\$3$ and each Type Q sells for $\\$5$, what is the maximum possible revenue?', NULL, $lyceon_json$[{"key":"A","text":"$\\$66$"},{"key":"B","text":"$\\$68$"},{"key":"C","text":"$\\$70$"},{"key":"D","text":"$\\$73$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $p$ be the number of Type P and $q$ be the number of Type Q. The constraints are $7p + 11q \\leq 154$, $p \\geq 6$. Since Type Q has a higher price per unit and revenue is maximized by making as many of Type Q as possible, set $p = 6$ (the minimum). Then $7(6) + 11q \\leq 154$ gives $42 + 11q \\leq 154$, so $11q \\leq 112$ and $q \\leq 10.18$, meaning $q = 10$. Revenue is $6(3) + 10(5) = 18 + 50 = \\$68$. The answer $\\$66$ comes from trying $p = 7$ and $q = 9$, which yields $21 + 45 = 66$, a valid but non-optimal choice. The answer $\\$70$ comes from ignoring the constraint $p \\geq 6$ and computing $14 \\times 5 = 70$ with all Type Q. The answer $\\$73$ results from an arithmetic error such as computing $42 + 11(10) = 152$ but then claiming $q = 11$ fits.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KOU34N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A laboratory has 1,200 bacterial cultures. After a treatment, $65\\%$ of the cultures are eliminated. Of the surviving cultures, $40\\%$ develop resistance. How many cultures develop resistance?', NULL, $lyceon_json$[{"key":"A","text":"$168$"},{"key":"B","text":"$216$"},{"key":"C","text":"$312$"},{"key":"D","text":"$480$"}]$lyceon_json$::jsonb, 'A', NULL, E'After the treatment, $1200 \\times (1 - 0.65) = 1200 \\times 0.35 = 420$ cultures survive. Of those, $420 \\times 0.40 = 168$ cultures develop resistance. The value $216$ results from an arithmetic slip such as computing $1 - 0.65$ as $0.45$ instead of $0.35$, giving $1200 \\times 0.45 \\times 0.40 = 216$. The value $312$ comes from incorrectly computing $40\\%$ of the eliminated cultures ($1200 \\times 0.65 \\times 0.40 = 312$) rather than the surviving ones. The value $480$ results from computing $40\\%$ of the original 1,200 cultures, ignoring the elimination step entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KWMZ3T', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'If $5x + 3y = 59$ and $5x - 3y = 11$, what is the value of $x - y$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$1$"},{"key":"C","text":"$15$"},{"key":"D","text":"$-3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding the two equations eliminates $y$: $(5x + 3y) + (5x - 3y) = 59 + 11$, giving $10x = 70$, so $x = 7$. Subtracting the second equation from the first eliminates $x$: $(5x + 3y) - (5x - 3y) = 59 - 11$, giving $6y = 48$, so $y = 8$. Therefore $x - y = 7 - 8 = -1$. The value $1$ results from reversing the subtraction order and computing $y - x$ instead of $x - y$. The value $15$ is $x + y = 7 + 8$, which answers the wrong expression. The value $-3$ results from an arithmetic error when solving for $y$, such as computing $6y = 42$ instead of $6y = 48$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LH8FRP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A school district wants to determine whether a new reading program improves student comprehension scores. District officials compare scores from 130 students who voluntarily enrolled in the program with scores from 130 students who did not enroll. The enrolled students score an average of 17 points higher. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new reading program causes an average improvement of 17 points in comprehension scores."},{"key":"B","text":"There is an association between enrollment in the program and higher comprehension scores, but a causal relationship cannot be established."},{"key":"C","text":"The new reading program has no effect on comprehension scores because the sample size is too small."},{"key":"D","text":"Students who did not enroll would have scored 17 points higher had they enrolled."}]$lyceon_json$::jsonb, 'B', NULL, E'Because students voluntarily chose whether to enroll, this is an observational study rather than a randomized experiment. Self-selection means that students who enrolled may differ from those who did not in motivation, prior ability, or other confounding variables. Therefore, a causal claim is not supported. The claim that the program causes the improvement is invalid because voluntary enrollment introduces confounding factors that prevent causal inference. The claim that the program has no effect because of sample size is incorrect; 130 per group is a reasonable sample size, and the issue is study design, not sample size. The claim that non-enrolled students would gain 17 points if enrolled incorrectly generalizes the observed difference to a counterfactual without random assignment to control for confounders.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LKLAP1', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many valid solutions does the equation $\\frac{x}{x - 3} = \\frac{3}{x - 3} + 2$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"Infinitely many"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiplying both sides by $(x - 3)$ gives $x = 3 + 2(x - 3) = 3 + 2x - 6 = 2x - 3$. Solving: $x = 2x - 3$, so $x = 3$. However, $x = 3$ makes the denominator $x - 3 = 0$, so it is extraneous and must be rejected. The equation has $0$ valid solutions. Choosing $1$ solution results from failing to check whether the algebraic solution is excluded by the domain restriction. Choosing $2$ solutions comes from misapplying the clearing step. Choosing infinitely many misinterprets the structure as an identity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LOTXB1', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $kx - 5y = 23$ and $6x - 15y = 42$ has no solution. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$18$"},{"key":"D","text":"$\\frac{23}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'A system has no solution when the lines are parallel: the ratios of the coefficients of $x$ and $y$ are equal, but the ratio of the constants differs. The second equation $6x - 15y = 42$ can be divided by 3 to give $2x - 5y = 14$. For parallel lines, the first equation must have the same coefficient ratio, so $\\frac{k}{6} = \\frac{-5}{-15} = \\frac{1}{3}$, giving $k = 2$. Checking: with $k = 2$, the first equation is $2x - 5y = 23$, and $23 \\neq 14$, confirming no solution. The value $-2$ results from incorrectly introducing a negative sign when computing the ratio. The value $18$ comes from inverting the coefficient ratio, computing $\\frac{k}{6} = \\frac{-15}{-5} = 3$ and getting $k = 18$. The value $\\frac{23}{7}$ comes from incorrectly setting the ratio of constants equal to the ratio of coefficients, solving $\\frac{k}{6} = \\frac{23}{42}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M02W1Q', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'A gym membership costs $\\$29$ per month after an initial enrollment fee of $\\$58$. If Keisha has paid a total of $\\$319$ over the course of her membership, for how many months has she been a member?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$11$"},{"key":"C","text":"$13$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'A', NULL, E'Set up the equation $29m + 58 = 319$. Subtract $58$ from both sides: $29m = 261$. Divide by $29$: $m = 9$. The value $11$ results from dividing the total $319$ by $29$ without first subtracting the enrollment fee, stopping one step short of the correct setup. The value $13$ comes from adding the enrollment fee instead of subtracting it ($319 + 58 = 377$, then $377 \\div 29 = 13$), a sign error on the fee. The value $10$ arises from subtracting one month''s cost instead of the enrollment fee ($319 - 29 = 290$, then $290 \\div 29 = 10$), confusing which value to subtract.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N79EU2', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'A line in the $xy$-plane has the equation $5x + 9y = 45$. What is the $x$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$5$"},{"key":"C","text":"$-9$"},{"key":"D","text":"$\\frac{5}{9}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $x$-intercept occurs when $y = 0$. Substituting: $5x = 45$, so $x = 9$. The value $5$ results from setting $x = 0$ instead and solving for $y$ ($9y = 45$, $y = 5$), which gives the $y$-intercept rather than the $x$-intercept. The value $-9$ incorrectly applies a negative sign to the correct answer. The value $\\frac{5}{9}$ confuses the slope of the line (in slope-intercept form, $y = -\\frac{5}{9}x + 5$, the slope is $-\\frac{5}{9}$) with the intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ODO01R', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A swimming pool has a cross-section in the shape of a trapezoid. The shallow end has a depth of $3$ feet, the deep end has a depth of $11$ feet, and the distance from the shallow end to the deep end along the bottom is $40$ feet. The pool is $18$ feet wide. What is the volume, in cubic feet, of the pool?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5040', ARRAY['5040'], E'The cross-section of the pool is a trapezoid with parallel sides (the depths) of $3$ feet and $11$ feet and a height (the horizontal length) of $40$ feet. The area of this trapezoidal cross-section is $\\frac{1}{2}(3 + 11)(40) = \\frac{1}{2}(14)(40) = 280$ square feet. Since the pool has a uniform width of $18$ feet, the volume is the cross-sectional area times the width: $280 \\times 18 = 5040$ cubic feet.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OGJG6Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'Circle $O$ has diameter $\\overline{AB}$. Point $C$ lies on the circle such that $\\angle CAB = 27°$. What is the measure, in degrees, of arc $BC$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '54', ARRAY['54'], E'Point $C$ lies on the circle and $\\overline{AB}$ is a diameter. The inscribed angle $\\angle CAB$ intercepts arc $BC$. By the inscribed angle theorem, the measure of an inscribed angle is half the measure of its intercepted arc. Therefore, arc $BC = 2 \\times 27 = 54°$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OW6Z6K', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $PQR$ with $\\angle Q = 90°$, $PQ = 9$ and $QR = 40$. Point $S$ lies on $\\overline{PR}$ such that $\\overline{QS}$ is perpendicular to $\\overline{PR}$. What is the length of $QS$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{360}{41}$"},{"key":"B","text":"$\\frac{180}{41}$"},{"key":"C","text":"$\\frac{81}{41}$"},{"key":"D","text":"$6\\sqrt{10}$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, find the hypotenuse: $PR = \\sqrt{9^2 + 40^2} = \\sqrt{81 + 1600} = \\sqrt{1681} = 41$. The area of triangle $PQR$ is $\\frac{1}{2} \\cdot PQ \\cdot QR = \\frac{1}{2} \\cdot 9 \\cdot 40 = 180$. Using $PR$ as the base with altitude $QS$: $\\frac{1}{2} \\cdot 41 \\cdot QS = 180$, so $QS = \\frac{360}{41}$. The value $\\frac{180}{41}$ results from dividing the area by the hypotenuse without the factor of $2$, forgetting that $\\text{Area} = \\frac{1}{2} \\cdot \\text{base} \\cdot \\text{height}$. The value $\\frac{81}{41}$ equals $\\frac{PQ^2}{PR}$, which is the length of the projection $PS$ (not the altitude $QS$), confusing the altitude with the leg projection. The value $6\\sqrt{10}$ equals $\\sqrt{PQ \\cdot QR} = \\sqrt{360}$, which confuses the geometric mean of the legs with the altitude to the hypotenuse formula $QS = \\frac{PQ \\cdot QR}{PR}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P4OZ6V', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of hours spent studying and the score on a skills test for 50 participants. The line of best fit is $y = 4.7x + 29$, where $x$ is the number of hours and $y$ is the predicted score. According to this model, what is the predicted increase in score for each additional 3 hours of studying?', NULL, $lyceon_json$[{"key":"A","text":"$4.7$"},{"key":"B","text":"$14.1$"},{"key":"C","text":"$29$"},{"key":"D","text":"$43.1$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope of the line of best fit is $4.7$, which represents the predicted increase in score for each additional hour of studying. For 3 additional hours, the predicted increase is $4.7 \\times 3 = 14.1$. The value $4.7$ is the increase per single hour, not per 3 hours. The value $29$ is the $y$-intercept, which represents the predicted score at $x = 0$ hours, not a rate of change. The value $43.1$ comes from incorrectly computing $4.7 \\times 3 + 29 = 43.1$, which gives a predicted score at $x = 3$ rather than the increase over 3 hours.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q78L8X', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'If $x^2 + y^2 = 74$ and $y = x + 2$, what is the product of all possible values of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$-35$"},{"key":"B","text":"$35$"},{"key":"C","text":"$-2$"},{"key":"D","text":"$37$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $y = x + 2$ into $x^2 + y^2 = 74$ gives $x^2 + (x + 2)^2 = 74$, which expands to $x^2 + x^2 + 4x + 4 = 74$, or $2x^2 + 4x - 70 = 0$. Dividing by $2$: $x^2 + 2x - 35 = 0$. Factoring: $(x + 7)(x - 5) = 0$, so $x = -7$ or $x = 5$. The product is $(-7)(5) = -35$. Choosing $35$ results from a sign error when multiplying a negative by a positive. Choosing $-2$ gives the sum of the roots instead of the product. Choosing $37$ comes from an arithmetic slip in the expansion step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QDPLUV', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'Given the system of equations $7x - 2y = 19$ and $3x + 2y = 31$, what is the value of $y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Adding the two equations eliminates $y$: $(7x - 2y) + (3x + 2y) = 19 + 31$, which simplifies to $10x = 50$, so $x = 5$. Substituting into the second equation gives $3(5) + 2y = 31$, so $15 + 2y = 31$, which yields $2y = 16$ and $y = 8$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QO1H9D', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $f(x) = -2x^2 + 28x - 91$ has a maximum value. What is the $x$-coordinate at which this maximum occurs?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'For a quadratic $f(x) = ax^2 + bx + c$ with $a < 0$, the maximum occurs at the vertex. The $x$-coordinate of the vertex is $x = \\frac{-b}{2a} = \\frac{-28}{2(-2)} = \\frac{-28}{-4} = 7$. Alternatively, completing the square: $f(x) = -2(x^2 - 14x) - 91 = -2(x^2 - 14x + 49 - 49) - 91 = -2(x - 7)^2 + 98 - 91 = -2(x - 7)^2 + 7$, confirming the vertex $x$-coordinate is $7$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QPJDOV', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to the equation $x^2 - 13x + 42 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 6$ and $x = 7$"},{"key":"B","text":"$x = -6$ and $x = -7$"},{"key":"C","text":"$x = 6$ and $x = -7$"},{"key":"D","text":"$x = 1$ and $x = 42$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring: $x^2 - 13x + 42 = (x - 6)(x - 7) = 0$, so $x = 6$ or $x = 7$. The pair $x = -6$ and $x = -7$ results from incorrectly negating both roots. The pair $x = 6$ and $x = -7$ results from a sign error on one factor. The pair $x = 1$ and $x = 42$ comes from listing factor pairs of $42$ without checking that they sum to $13$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2REVWPL', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'Which of the following points $(x, y)$ is a solution to the system of inequalities $y < -3x + 17$ and $y \\geq x + 1$?', NULL, $lyceon_json$[{"key":"A","text":"$(6, 2)$"},{"key":"B","text":"$(2, 5)$"},{"key":"C","text":"$(4, 8)$"},{"key":"D","text":"$(1, -1)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Testing $(2, 5)$: the first inequality gives $5 < -3(2) + 17 = 11$, which is true, and the second gives $5 \\geq 2 + 1 = 3$, which is true, so $(2, 5)$ satisfies both. Testing $(6, 2)$: $2 < -3(6) + 17 = -1$ is false, so it fails the first inequality. Testing $(4, 8)$: $8 < -3(4) + 17 = 5$ is false, so it fails the first inequality. Testing $(1, -1)$: while $-1 < -3(1) + 17 = 14$ is true, $-1 \\geq 1 + 1 = 2$ is false, so it fails the second inequality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RJBFFP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of 400 adults in a city finds that $58\\%$ support a proposed park renovation, with a margin of error of $4.1$ percentage points at a $95\\%$ confidence level. Which of the following is a valid conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Between $53.9\\%$ and $62.1\\%$ of all adults in the city support the renovation."},{"key":"B","text":"Exactly $58\\%$ of all adults in the city support the renovation."},{"key":"C","text":"Between $53.9\\%$ and $62.1\\%$ of the 400 sampled adults support the renovation."},{"key":"D","text":"If another sample of 400 is taken, exactly $58\\%$ will support the renovation."}]$lyceon_json$::jsonb, 'A', NULL, E'The confidence interval is $58\\% \\pm 4.1\\%$, which gives the range $53.9\\%$ to $62.1\\%$. This interval estimates the true proportion for all adults in the city, not just the sample. The claim that exactly $58\\%$ of all adults support the renovation confuses a sample statistic with a population parameter and ignores sampling variability. The claim that the interval applies to the 400 sampled adults misapplies the margin of error, which describes uncertainty about the population, not the sample whose proportion is already known. The claim that a new sample would yield exactly $58\\%$ incorrectly treats sample statistics as fixed rather than variable across samples.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S849GG', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $7x + 28 = 91$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$13$"},{"key":"C","text":"$17$"},{"key":"D","text":"$-9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtract $28$ from both sides to get $7x = 63$, then divide both sides by $7$ to find $x = 9$. The value $13$ results from dividing $91$ by $7$ without first subtracting $28$, which gives the quotient of the total rather than isolating $x$. The value $17$ comes from adding $28$ to $91$ instead of subtracting ($119 \\div 7 = 17$), reversing the operation. The value $-9$ applies the correct magnitude but reverses the sign.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SPXSBI', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'Given the system of equations $3x + y = 29$ and $y = 2x - 1$, what is the value of $y$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$11$"},{"key":"C","text":"$30$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $y = 2x - 1$ into the first equation gives $3x + (2x - 1) = 29$, so $5x - 1 = 29$, which gives $5x = 30$ and $x = 6$. Then $y = 2(6) - 1 = 11$. The value 6 is $x$, not the requested $y$, resulting from answering the wrong variable. The value 30 comes from computing $5x = 30$ but stopping before dividing by 5 and then not substituting back. The value 13 results from an arithmetic error such as computing $y = 2(6) + 1 = 13$ instead of $2(6) - 1$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TKH17V', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A recipe calls for $\\frac{7}{4}$ cups of oats to make 14 granola bars. At this rate, how many cups of oats are needed to make 56 granola bars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The rate is $\\frac{7/4}{14} = \\frac{7}{56} = \\frac{1}{8}$ cups per granola bar. For 56 granola bars, the amount needed is $\\frac{1}{8} \\times 56 = 7$ cups. Alternatively, since $56 = 4 \\times 14$, the amount is $4 \\times \\frac{7}{4} = 7$ cups.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TKQHAE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $WXY$, the right angle is at $X$. If $\\cos(W) = \\frac{5}{13}$ and $WX = 35$, what is the length of $WY$?', NULL, $lyceon_json$[{"key":"A","text":"$91$"},{"key":"B","text":"$84$"},{"key":"C","text":"$\\frac{175}{13}$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'In right triangle $WXY$ with the right angle at $X$, side $WY$ is the hypotenuse, and $WX$ is the side adjacent to angle $W$. Therefore $\\cos(W) = \\frac{WX}{WY} = \\frac{35}{WY} = \\frac{5}{13}$. Solving gives $WY = 35 \\cdot \\frac{13}{5} = 91$. The value $84$ is the length of the other leg $XY = \\sqrt{91^2 - 35^2} = \\sqrt{8281 - 1225} = \\sqrt{7056} = 84$, which answers for the wrong side. The value $\\frac{175}{13}$ comes from multiplying $35 \\cdot \\frac{5}{13}$ instead of $35 \\cdot \\frac{13}{5}$, inverting the ratio. The value $7$ comes from computing $\\frac{35}{5} = 7$ and stopping, extracting only the denominator''s factor without completing the proportion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UI0WVQ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $9$. What is the length of an arc that subtends a central angle of $80°$?', NULL, $lyceon_json$[{"key":"A","text":"$2\\pi$"},{"key":"B","text":"$4\\pi$"},{"key":"C","text":"$8\\pi$"},{"key":"D","text":"$18\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'Arc length equals $\\frac{\\theta}{360} \\cdot 2\\pi r = \\frac{80}{360} \\cdot 2\\pi(9) = \\frac{2}{9} \\cdot 18\\pi = 4\\pi$. The value $2\\pi$ results from using $\\pi r$ instead of $2\\pi r$ for the circumference: $\\frac{80}{360} \\cdot 9\\pi = 2\\pi$, omitting the factor of $2$. The value $8\\pi$ results from reducing $\\frac{80}{360}$ incorrectly as $\\frac{4}{9}$ instead of $\\frac{2}{9}$, giving $\\frac{4}{9} \\cdot 18\\pi = 8\\pi$. The value $18\\pi$ is the sector area $\\frac{80}{360} \\cdot \\pi r^2 = \\frac{2}{9} \\cdot 81\\pi = 18\\pi$, confusing arc length with sector area.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ULC1ZS', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $x^2 - 9x + 14 = 0$ and $x > 5$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Factoring: $x^2 - 9x + 14 = (x - 2)(x - 7) = 0$, giving $x = 2$ or $x = 7$. Since $x > 5$, the answer is $x = 7$.', NULL, NULL, 'draft', 1, 55, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ULEWKG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set contains 11 values: 3, 7, 7, 9, 12, 15, 15, 15, 21, 26, 33. If the value 33 is replaced by 97, which of the following measures changes?', NULL, $lyceon_json$[{"key":"A","text":"Median only"},{"key":"B","text":"Mean only"},{"key":"C","text":"Both the median and the mean"},{"key":"D","text":"Neither the median nor the mean"}]$lyceon_json$::jsonb, 'B', NULL, E'The median of 11 values is the 6th value in sorted order, which is 15. Replacing 33 with 97 does not affect the position or value of the 6th element, so the median remains 15. The mean is $\\frac{3+7+7+9+12+15+15+15+21+26+33}{11} = \\frac{163}{11} \\approx 14.82$. After the replacement, the sum becomes $163 - 33 + 97 = 227$, giving a new mean of $\\frac{227}{11} \\approx 20.64$. Therefore only the mean changes. The choice stating that the median only changes is wrong because the 6th value remains 15 regardless. The choice stating both change incorrectly assumes the outlier shift affects the median. The choice stating neither changes ignores the effect on the sum used to compute the mean.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V565VZ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $4(3x + 5) - 11 = 69$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$\\frac{23}{4}$"},{"key":"D","text":"$\\frac{20}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distribute the $4$: $12x + 20 - 11 = 69$, which simplifies to $12x + 9 = 69$. Subtract $9$: $12x = 60$. Divide by $12$: $x = 5$. The value $-5$ reverses the sign of the correct answer. The value $\\frac{23}{4}$ results from ignoring the constants entirely and setting $12x = 69$, so $x = \\frac{69}{12} = \\frac{23}{4}$. The value $\\frac{20}{3}$ comes from distributing $4$ only to $3x$ (getting $12x$) but not to $5$, yielding $12x - 11 = 69$, then $12x = 80$ and $x = \\frac{80}{12} = \\frac{20}{3}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VN3W9U', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'If $a$ and $b$ are the solutions to $2x^2 - 14x + 17 = 0$, what is the value of $\\frac{1}{a} + \\frac{1}{b}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{14}{17}$"},{"key":"B","text":"$\\frac{17}{14}$"},{"key":"C","text":"$\\frac{7}{17}$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'By Vieta''s formulas for $2x^2 - 14x + 17 = 0$: the sum of roots is $a + b = \\frac{14}{2} = 7$ and the product of roots is $ab = \\frac{17}{2}$. Therefore $\\frac{1}{a} + \\frac{1}{b} = \\frac{a + b}{ab} = \\frac{7}{17/2} = \\frac{14}{17}$. Choosing $\\frac{17}{14}$ inverts the fraction, confusing numerator and denominator. Choosing $\\frac{7}{17}$ omits the factor of $2$ when dividing by $ab = \\frac{17}{2}$. Choosing $7$ gives just the sum of roots without applying the reciprocal operation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VOGGK1', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{25x^2 - 49}{5x - 7}$ for $x \\neq \\frac{7}{5}$?', NULL, $lyceon_json$[{"key":"A","text":"$5x - 7$"},{"key":"B","text":"$5x + 7$"},{"key":"C","text":"$25x + 7$"},{"key":"D","text":"$5x - 49$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $25x^2 - 49$ is a difference of squares: $(5x)^2 - 7^2 = (5x - 7)(5x + 7)$. Dividing by $5x - 7$ yields $5x + 7$. Choosing $5x - 7$ reflects a sign error in identifying the remaining factor. Choosing $25x + 7$ incorrectly keeps the squared coefficient. Choosing $5x - 49$ results from failing to complete the factorization.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WLA7SK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Triangle $JKL$ is isosceles with $JK = KL$, and $\\angle K$ measures $52°$. What is the measure, in degrees, of $\\angle J$?', NULL, $lyceon_json$[{"key":"A","text":"$52$"},{"key":"B","text":"$64$"},{"key":"C","text":"$128$"},{"key":"D","text":"$76$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since triangle $JKL$ is isosceles with $JK = KL$, the base angles $\\angle J$ and $\\angle L$ are equal. The sum of angles in a triangle is $180°$, so $\\angle J + \\angle L + 52 = 180$. Because $\\angle J = \\angle L$, we get $2 \\cdot \\angle J = 128$, giving $\\angle J = 64$. The value $52$ comes from assuming all three angles are equal to the vertex angle, confusing isosceles with equilateral. The value $128$ results from computing $180 - 52 = 128$ but forgetting to divide by $2$ to split the remaining degrees between the two base angles. The value $76$ results from an arithmetic error in dividing, such as computing $\\frac{152}{2}$ instead of $\\frac{128}{2}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X5IEGW', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'The expression $\\frac{7}{x - 5} + \\frac{3}{x + 2}$ can be written as $\\frac{ax + b}{(x - 5)(x + 2)}$, where $a$ and $b$ are constants. What is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$29$"},{"key":"C","text":"$-29$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'A', NULL, E'Combining fractions: $\\frac{7(x + 2) + 3(x - 5)}{(x - 5)(x + 2)} = \\frac{7x + 14 + 3x - 15}{(x - 5)(x + 2)} = \\frac{10x - 1}{(x - 5)(x + 2)}$. So $a = 10$ and $b = -1$. Choosing $29$ results from adding $14 + 15$ instead of computing $14 - 15$, a sign error. Choosing $-29$ comes from an arithmetic slip in combining the constants. Choosing $1$ reverses the sign of $b$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z8K0AY', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{2x^3 + 11x^2 + 11x - 12}{x + 3} = ax^2 + bx + c$ for constants $a$, $b$, and $c$, what is the value of $a + b + c$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$11$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using synthetic division with root $-3$: bring down $2$; $2 \\times (-3) = -6$; $11 + (-6) = 5$; $5 \\times (-3) = -15$; $11 + (-15) = -4$; $-4 \\times (-3) = 12$; $-12 + 12 = 0$. The quotient is $2x^2 + 5x - 4$, so $a = 2$, $b = 5$, $c = -4$, and $a + b + c = 2 + 5 + (-4) = 3$. Choosing $-3$ results from a sign error in the constant term. Choosing $11$ comes from reading the coefficient of $x^2$ in the original polynomial rather than performing the division. Choosing $7$ results from adding only $a + b$ and omitting $c$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZUSMHR', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'In the $xy$-plane, line $k$ is parallel to the line $3x + 8y = 24$ and passes through the point $(4, -7)$. What is the $y$-intercept of line $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-11/2', ARRAY['-11/2', '-5.5'], E'First find the slope of the given line by rewriting in slope-intercept form: $8y = -3x + 24$, so $y = -\\frac{3}{8}x + 3$. The slope is $-\\frac{3}{8}$. Since line $k$ is parallel, it has the same slope. Using point-slope form with $(4, -7)$: $y + 7 = -\\frac{3}{8}(x - 4)$. Distribute: $y + 7 = -\\frac{3}{8}x + \\frac{3}{2}$. Subtract $7$: $y = -\\frac{3}{8}x + \\frac{3}{2} - \\frac{14}{2} = -\\frac{3}{8}x - \\frac{11}{2}$. The $y$-intercept is $-\\frac{11}{2}$. A common error is using the perpendicular slope $\\frac{8}{3}$ instead of the parallel slope $-\\frac{3}{8}$, which yields a different intercept. Another error is using the given line''s $y$-intercept of $3$ without accounting for the new point.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2167OOY', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Based on the text, what can most reasonably be inferred about the practical implications of Katsaros''s findings for architectural preservation?', E'Conservation architect Eleni Katsaros investigated moisture migration patterns in 19 limestone-clad heritage buildings across Thessaloniki, Greece, between 2018 and 2023. She found that buildings treated with modern hydrophobic silicone coatings showed substantially less surface staining than untreated buildings over the five-year period. However, infrared thermography revealed that moisture blocked by the coatings migrated inward, accumulating in the structural brick behind the limestone cladding. In untreated buildings, moisture evaporated outward through the limestone''s natural porosity, keeping interior brick layers comparatively dry. Katsaros measured that the coated buildings'' interior brick had an average moisture content 34 percent higher than that of untreated buildings, and she documented early-stage salt crystallization damage in the brick of 11 of the 19 coated structures. She noted that salt crystallization within brick substrates is a well-established precursor to irreversible structural spalling.', $lyceon_json$[{"key":"A","text":"Hydrophobic coatings may protect the visible limestone surfaces of heritage buildings from staining while accelerating hidden deterioration of the structural brick substrate beneath the cladding."},{"key":"B","text":"Heritage buildings in Thessaloniki should be preserved without any surface treatments, since Katsaros's study demonstrates that untreated limestone is inherently more durable than limestone protected by any modern conservation technology currently available."},{"key":"C","text":"The salt crystallization damage Katsaros observed is unlikely to progress to structural spalling because the hydrophobic coatings will eventually degrade and allow the trapped moisture to evaporate outward through the limestone as it would in untreated buildings."},{"key":"D","text":"Infrared thermography is a more reliable diagnostic tool for assessing heritage building condition than traditional visual inspection methods, which can overlook subsurface moisture problems that compromise long-term structural integrity across diverse masonry types."}]$lyceon_json$::jsonb, 'A', NULL, E'Katsaros found that hydrophobic coatings reduced visible surface staining but drove moisture inward, increasing brick moisture content by 34 percent and causing early-stage salt crystallization in most coated buildings. Since salt crystallization is a precursor to irreversible spalling, one can infer that these coatings protect visible surfaces while accelerating hidden structural damage. The option recommending no surface treatments overstates the findings; Katsaros studied one type of coating and did not evaluate all conservation technologies. The option predicting that coating degradation will resolve the problem introduces speculative reasoning the passage does not support and ignores that Katsaros described the crystallization damage as a precursor to irreversible spalling. The option about infrared thermography as a superior diagnostic tool draws a broad methodological conclusion the passage does not make; Katsaros used thermography as one instrument, not as the subject of a comparative evaluation of inspection techniques.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22I2SRY', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the text, what can most reasonably be inferred about the participants'' performance on spatial reasoning tasks?', E'Psychologist Henrik Sjolund conducted a 2022 experiment in which 74 participants completed a battery of spatial reasoning puzzles under two conditions. In the first condition, participants worked in a room with a consistent ambient temperature of 22 degrees Celsius. In the second condition, the same participants worked in a room where the temperature cycled unpredictably between 18 and 27 degrees Celsius at irregular intervals. Puzzle accuracy did not differ meaningfully between conditions, but participants in the variable-temperature room took an average of 19 percent longer to complete each puzzle. Sjolund suggested that the cognitive resources diverted to processing environmental discomfort did not reduce accuracy because participants compensated by slowing their pace, effectively trading speed for maintained precision.', $lyceon_json$[{"key":"A","text":"Participants in the variable-temperature condition maintained their accuracy by allocating additional time to each puzzle, offsetting the cognitive cost of environmental distraction."},{"key":"B","text":"Spatial reasoning ability is largely unaffected by environmental conditions, suggesting that cognitive resources devoted to spatial tasks operate independently of those processing physical discomfort."},{"key":"C","text":"Participants found the variable-temperature condition less stressful than expected, which is why their accuracy remained comparable to performance in the stable-temperature condition."},{"key":"D","text":"The 19 percent increase in completion time was caused primarily by participants pausing between puzzles to adjust their clothing or posture in response to temperature fluctuations rather than by slower cognitive processing during the puzzles themselves."}]$lyceon_json$::jsonb, 'A', NULL, E'Sjolund explicitly suggested that participants compensated for cognitive resources diverted to environmental discomfort by slowing their pace, trading speed for maintained precision. The inference that additional time allocation preserved accuracy follows directly. The option about spatial reasoning operating independently of discomfort contradicts Sjolund''s interpretation; he posited that discomfort did draw cognitive resources, and participants had to compensate. The option about participants finding the condition less stressful introduces a claim the passage does not support; the passage describes environmental discomfort as a real cognitive cost. The option attributing the time increase to physical adjustments between puzzles proposes a behavioral explanation the passage never mentions; Sjolund frames the slowdown as a cognitive compensation strategy during the tasks.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27PGYE2', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research brief and wants to present Dr. Okonkwo''s findings as promising while also cautioning that the results may not generalize beyond the study''s specific conditions. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes on Dr. Adaeze Okonkwo''s soil remediation research:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW296UO0S', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Soil salinity has become a growing concern for rice farmers in the Mekong Delta, where rising sea levels have pushed saltwater further inland during dry seasons. <u>A 2022 survey by the Vietnamese Ministry of Agriculture found that 38 percent of paddies in Ben Tre province had salt concentrations exceeding the threshold for standard rice cultivation.</u> In response, agricultural extension workers have begun distributing salt-tolerant rice varieties developed at Can Tho University, and early field trials suggest these cultivars maintain yields even at elevated salinity levels.', $lyceon_json$[{"key":"A","text":"It supplies a quantitative finding that demonstrates the severity of the problem introduced in the first sentence"},{"key":"B","text":"It proposes a solution to the environmental challenge discussed throughout the rest of the passage"},{"key":"C","text":"It questions the reliability of earlier research on saltwater intrusion in the Mekong Delta region"},{"key":"D","text":"It establishes the historical context for rice farming practices that the final sentence goes on to describe"}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence presents a specific statistic from a government survey showing that 38 percent of paddies exceeded salt thresholds, directly illustrating the severity of the salinity concern introduced in the opening sentence. The option about proposing a solution is wrong because the underlined sentence reports a problem measurement, not a remedy; the solution (salt-tolerant varieties) appears in the final sentence. The option about questioning earlier research is wrong because the survey provides new data supporting the salinity concern rather than challenging previous findings. The option about establishing historical context is wrong because the survey reports a recent finding about current conditions, not a historical background for farming practices.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B8RF6P', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, which choice best describes a difference in how the two researchers understand the function of ritualized gift exchange in early medieval societies?', E'Text 1: Historian Brynja Sigurdardottir contends that gift exchange among ninth-century Norse chieftains served primarily as a mechanism for establishing hierarchical relationships. Drawing on saga literature and runic inscriptions, Sigurdardottir argues that the value and rarity of a gift encoded the giver''s social rank relative to the recipient: a chieftain who bestowed a sword of superior craftsmanship asserted dominance, while the recipient''s acceptance constituted a public acknowledgment of subordinate status. In this framework, refusing a gift was one of the few available means of contesting an imposed hierarchy.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BOM2B4', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "economy" most nearly mean?', E'Critics have long admired the <u>economy</u> of Emily Dickinson''s verse, noting how her tightly compressed lines achieve emotional resonance through strategic omission rather than elaboration. Poet and scholar Adaeze Okonkwo observes that Dickinson''s dashes function as structural hinges, allowing a six-word line to carry the argumentative weight that most nineteenth-century poets required an entire stanza to develop. This compression, Okonkwo argues, demands that each syllable perform double duty, bearing both sonic and semantic obligations simultaneously.', $lyceon_json$[{"key":"A","text":"efficient use of limited expressive resources"},{"key":"B","text":"financial management of publishing expenses"},{"key":"C","text":"large-scale system of commercial production and trade"},{"key":"D","text":"deliberate avoidance of emotionally charged subject matter"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage discusses Dickinson''s compressed lines, strategic omission, and syllables performing double duty, all describing a writer who achieves maximum effect with minimal material. The word "economy" here means efficient use of limited expressive resources. The option about financial management of publishing expenses applies the monetary sense of economy to a literary discussion where no financial matters are mentioned. The option about a large-scale system of commercial production and trade refers to the macroeconomic sense of the word, which is entirely unrelated to poetic technique. The option about deliberate avoidance of emotionally charged subject matter contradicts the passage, which states that Dickinson''s verse achieves emotional resonance, not that it avoids emotional content.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C8LJU8', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a report on music education and wants to counter the claim that instrumental training has no measurable cognitive benefit for children. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes on a longitudinal study by Dr. Kofi Mensah:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CAIQ0N', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Cognitive scientist Renata Oliveira conducted a 2023 study in which 112 bilingual Portuguese-English speakers were asked to estimate the durations of events described in short narratives. When participants read narratives in Portuguese, they consistently overestimated the durations of emotionally charged events by an average of 23 percent compared to neutral events. The same participants reading structurally identical narratives in English showed no statistically significant difference in duration estimates between emotional and neutral events. Oliveira proposed that the participants'' first language activates deeper affective processing, which distorts temporal perception, while their second language creates a cognitive distance that insulates time estimation from emotional interference. She cautioned, however, that the effect may not generalize to bilinguals who acquired both languages simultaneously in early childhood.', $lyceon_json$[{"key":"A","text":"Bilingual speakers who acquired both languages simultaneously during early childhood are likely to show temporal distortion effects similar to those observed in Oliveira's Portuguese-dominant participants when reading emotional narratives."},{"key":"B","text":"Oliveira's study found that a bilingual speaker's first language amplifies the influence of emotion on time perception, whereas using a second language reduces that emotional interference with temporal judgment."},{"key":"C","text":"The study demonstrates that Portuguese encodes emotional content more intensely than English does, creating systematic differences in how speakers of each language perceive the passage of time during emotionally charged experiences."},{"key":"D","text":"Oliveira concluded that bilingualism fundamentally restructures the neural mechanisms of temporal perception, enabling bilingual individuals to toggle between emotionally engaged and emotionally detached modes of cognitive processing at will."}]$lyceon_json$::jsonb, 'B', NULL, E'Oliveira''s proposal is that a first language activates deeper affective processing that distorts temporal perception, while a second language creates cognitive distance that insulates time estimation from emotional interference. The option about first-language amplification and second-language reduction of emotional interference captures this idea precisely. The option about simultaneous bilinguals contradicts the passage: Oliveira cautioned the effect may not generalize to such speakers, rather than predicting they would show similar patterns. The option about Portuguese encoding emotion more intensely than English mischaracterizes the finding; the study compared a first language to a second language within the same speakers, not properties inherent to the languages themselves. The option about fundamentally restructured neural mechanisms overstates the findings; Oliveira described an effect on perception, not a claim about neural restructuring or volitional toggling.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CX6ZRX', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "currency" most nearly mean?', E'Among medieval historians, the longstanding debate over whether Viking-age Scandinavians used silver primarily as bullion or as minted coinage has gained new <u>currency</u> following excavations at Birka in 2021. Archaeologist Lars Ekdahl recovered 319 fragmented hack-silver pieces alongside 47 intact dirhams from a single hoard, suggesting that both practices coexisted in ways earlier scholars had not anticipated. The find has prompted a wave of reinterpretations across the field.', $lyceon_json$[{"key":"A","text":"monetary units used in commercial transactions"},{"key":"B","text":"widespread acceptance and attention"},{"key":"C","text":"foreign coins circulated across borders"},{"key":"D","text":"legal authority granted by a governing body"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that a debate has gained new "currency" after recent excavations prompted reinterpretations, indicating that the debate has gained widespread acceptance and attention. The option about monetary units refers to the financial sense of currency, which does not fit the context of a scholarly debate gaining prominence. The option about foreign coins circulated across borders conflates the passage''s subject matter (Viking-age silver) with the meaning of the target word, which here describes the debate''s status, not physical money. The option about legal authority granted by a governing body introduces a governmental meaning unrelated to the passage''s discussion of scholarly discourse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DRP3A8', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'A 2021 survey of 1,247 registered nurses found that 68 percent reported chronic sleep deprivation linked to rotating shift schedules. Hospitals that implemented fixed-shift policies saw absenteeism rates drop by 19 percent within eight months. ______ several hospital administrators noted that fixed shifts created staffing gaps during overnight hours, requiring expensive temporary agency contracts to maintain adequate patient-to-nurse ratios.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"In other words,"},{"key":"C","text":"However,"},{"key":"D","text":"As a result of these improvements,"}]$lyceon_json$::jsonb, 'C', NULL, E'The preceding sentences establish that fixed-shift policies produced a measurable benefit (lower absenteeism), while the sentence after the blank introduces a complication (staffing gaps and higher costs). "However," correctly signals this pivot from a positive outcome to an offsetting drawback. "Similarly," wrongly implies the staffing gaps parallel the benefit rather than counterbalance it. "In other words," incorrectly suggests the staffing problem restates the absenteeism finding. "As a result of these improvements," treats the staffing gaps as a consequence of reduced absenteeism, but the passage frames them as a consequence of the policy change itself, and the phrase mischaracterizes a drawback as flowing from an improvement.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E5LI1G', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Textile conservator Nadira Osei has developed a technique for stabilizing centuries-old silk tapestries without applying synthetic adhesives. By using a micro-suction method originally designed for semiconductor ______ Osei can remove particulate damage from fragile fibers one thread at a time.', $lyceon_json$[{"key":"A","text":"manufacturing,"},{"key":"B","text":"manufacturing;"},{"key":"C","text":"manufacturing"},{"key":"D","text":"manufacturing. And"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase "By using a micro-suction method originally designed for semiconductor manufacturing" is an introductory prepositional phrase modifying the main clause "Osei can remove particulate damage." A comma after an introductory phrase is the correct punctuation. A semicolon after "manufacturing" incorrectly treats the introductory phrase as an independent clause, but it has no subject-verb pair and cannot stand alone. Omitting punctuation entirely after "manufacturing" creates a run-on that merges the introductory phrase into the main clause without the required pause. Using a period followed by "And" fragments the introductory phrase into an incomplete sentence and begins a new sentence with a conjunction unnecessarily.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EXNV2R', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Historian Tomoko Arai''s analysis of 17th-century Dutch trade ledgers revealed that the price fluctuations of nutmeg between 1621 and 1659 correlated more closely with shifts in the Dutch East India Company''s internal shipping schedules than with actual harvest yields on the Banda Islands. When the Company delayed departures from Banda to consolidate smaller cargoes onto fewer vessels, nutmeg prices in Amsterdam rose sharply, even during seasons of record harvests. Arai argues that the commodity''s scarcity in European markets was often an artifact of logistical decisions rather than genuine supply shortages, complicating the standard narrative that equates rising spice prices with declining production.', $lyceon_json$[{"key":"A","text":"Arai's research indicates that nutmeg price increases in 17th-century Amsterdam frequently reflected the Dutch East India Company's shipping logistics rather than actual shortages at the point of production."},{"key":"B","text":"The Dutch East India Company deliberately restricted nutmeg shipments to inflate European market prices, a monopolistic strategy that historians have consistently recognized as the primary cause of 17th-century spice price volatility."},{"key":"C","text":"Harvest yields on the Banda Islands were far less predictable during the mid-1600s than earlier historians believed, leading to miscalculations in standard economic models of the early modern spice trade."},{"key":"D","text":"Trade ledgers from the 17th-century Dutch spice trade are more reliable primary sources for economic analysis than the Company's official correspondence and administrative records from the same period."}]$lyceon_json$::jsonb, 'A', NULL, E'Arai''s argument is that nutmeg scarcity in European markets was often an artifact of logistical decisions rather than genuine supply shortages. The option about shipping logistics driving price increases directly restates this finding. The option about deliberate price manipulation overstates the passage: Arai describes logistical decisions like cargo consolidation, not an intentional monopolistic strategy, and the passage does not say historians have consistently recognized this. The option about unpredictable harvest yields contradicts the passage, which notes record harvests occurred during some price spikes, suggesting yields were not the issue. The option about the reliability of trade ledgers as sources addresses methodology the passage does not discuss.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H32OPP', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a researcher, if accurate, would most effectively support the argument presented in the text?', E'Materials scientist Jochen Brandt has argued that the widespread adoption of recycled carbon fiber in automotive manufacturing is hindered not by the fiber''s structural performance but by the economics of reclamation. Virgin carbon fiber can be produced in continuous, uniform filaments ideally suited to automated layup processes, whereas recycled fiber emerges from pyrolysis as short, irregular strands that require labor-intensive hand layup or specialized molding. Brandt contends that until reclamation processes yield fibers compatible with existing automation, recycled carbon fiber will remain confined to low-volume, non-structural components despite meeting strength requirements for primary chassis elements.', $lyceon_json$[{"key":"A","text":"\"Our tensile tests confirm that pyrolysis-reclaimed carbon fiber retains 91 percent of virgin fiber's ultimate strength, more than sufficient for load-bearing automotive applications under standard crash-test protocols.\""},{"key":"B","text":"\"The bottleneck is not what the fiber can withstand but what the factory can do with it; current automated layup heads reject any strand shorter than 50 millimeters, and pyrolysis yields a median strand length of roughly 31 millimeters.\""},{"key":"C","text":"\"Consumer surveys consistently show that buyers are willing to pay a premium of up to 14 percent for vehicles marketed as containing recycled composite materials, which should incentivize manufacturers to invest in reclamation infrastructure.\""},{"key":"D","text":"\"Lifecycle analyses demonstrate that producing recycled carbon fiber generates 43 percent fewer carbon dioxide emissions than manufacturing an equivalent mass of virgin fiber from polyacrylonitrile precursor material.\""}]$lyceon_json$::jsonb, 'B', NULL, E'Brandt''s argument is that the barrier to recycled carbon fiber adoption is incompatibility with existing automated manufacturing processes, not structural inadequacy. The quotation about automated layup heads rejecting short strands from pyrolysis directly illustrates this manufacturing-compatibility barrier. The quotation about tensile strength retention supports the premise that recycled fiber is structurally adequate, but that premise is not in dispute; Brandt already concedes strength requirements are met. The quotation about consumer willingness to pay a premium concerns market demand, which does not address the manufacturing process limitation central to Brandt''s argument. The quotation about reduced carbon emissions addresses the environmental case for recycling but not the manufacturing economics Brandt identifies as the real obstacle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HUN1NI', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a summary for a science newsletter and wants to highlight the unexpected scale of plastic contamination found in a recent study. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes on Dr. Renata Szabo''s 2024 microplastics study:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I5Z4WN', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Pacific tree frog, commonly found across western North America, ______ its distinctive two-note call primarily during the spring breeding season. Researchers have noted that populations in urban areas tend to call at higher pitches to compensate for low-frequency traffic noise.', $lyceon_json$[{"key":"A","text":"produce"},{"key":"B","text":"producing"},{"key":"C","text":"produces"},{"key":"D","text":"are producing"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject is "The Pacific tree frog," a singular noun. The phrase "commonly found across western North America" is a participial phrase set off by commas that describes the frog but does not change the number of the subject. A singular subject requires the singular verb "produces." The plural form "produce" does not agree with the singular subject. The present participle "producing" alone is not a finite verb and cannot serve as the main verb of the sentence. The plural progressive "are producing" incorrectly treats the singular subject as plural.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JPKVBS', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Urban planner Kenji Muraoka has proposed redesigning three major intersections in downtown Sapporo to prioritize pedestrian flow over vehicular throughput. City officials have expressed cautious support for the ______ they insist on reviewing traffic simulation data before committing municipal funds, Muraoka has already begun collaborating with engineers at Hokkaido University to generate the required models.', $lyceon_json$[{"key":"A","text":"proposal. Because"},{"key":"B","text":"proposal, because"},{"key":"C","text":"proposal because"},{"key":"D","text":"proposal; because,"}]$lyceon_json$::jsonb, 'A', NULL, E'After the blank, "because they insist on reviewing traffic simulation data before committing municipal funds" is a subordinate clause that pairs with the main clause "Muraoka has already begun collaborating with engineers," forming a complete sentence. A period after "proposal" correctly ends the first sentence, and "Because" introduces a new sentence containing a subordinate clause followed by its main clause. Using a comma before "because" creates a comma splice, since the result is an independent clause ("City officials have expressed cautious support for the proposal") joined by only a comma to another full sentence. Omitting punctuation entirely before "because" produces a run-on that incorrectly attaches the "because" clause to the preceding independent clause while also connecting it to the following main clause, creating a confused structure. A semicolon before "because" with a misplaced comma after it incorrectly punctuates the subordinate conjunction and treats the dependent clause as though it were an independent element.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LGK3JF', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the ornithologists'' claim?', E'Ornithologists at the University of Bergen have claimed that the recent northward expansion of the Eurasian collared dove into subarctic Norway is driven primarily by milder winter temperatures rather than by changes in food availability. They note that collared doves rely on seeds from cultivated grain fields, which have not expanded northward during the same period. The researchers argue that warmer winters reduce cold-stress mortality, allowing the species to establish breeding populations in regions that were previously too harsh for year-round survival.', $lyceon_json$[{"key":"A","text":"Collared dove populations in southern Norway have remained stable over the past two decades despite significant increases in grain cultivation during that period."},{"key":"B","text":"Subarctic Norwegian weather stations that recorded the greatest winter temperature increases over the past 15 years correspond to the areas where collared dove breeding colonies first appeared."},{"key":"C","text":"Grain farmers in subarctic Norway have recently adopted cold-resistant barley cultivars, substantially increasing the winter seed supply available to ground-feeding bird species throughout the region."},{"key":"D","text":"Collared doves in subarctic Norway exhibit higher body fat reserves during winter months than conspecifics in temperate regions, indicating a physiological adaptation to colder climates that may predate the observed temperature changes."}]$lyceon_json$::jsonb, 'B', NULL, E'The ornithologists claim milder winters drive the northward expansion. A finding that the areas with the greatest winter warming are exactly where breeding colonies first appeared directly links temperature change to range expansion, supporting the claim. The option about stable populations in southern Norway despite increased grain cultivation is tangentially relevant to food availability but does not address the subarctic expansion. The option about cold-resistant barley cultivars would actually undermine the claim by introducing an alternative food-based explanation. The option about higher body fat reserves suggests a physiological adaptation predating warming, which would complicate rather than support the temperature-driven explanation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LPID5W', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "arrested" most nearly mean?', E'By the late 1870s, railway expansion across the Argentine pampas had <u>arrested</u> the seasonal migration patterns of the Ranquel people, whose centuries-old routes to highland grazing areas were severed by fenced rail corridors and private estancias. Ethnographer Catalina Ibarra notes that this disruption compelled Ranquel communities to adopt fixed settlement patterns within a single generation, fundamentally altering kinship structures that had depended on the rhythms of transhumance.', $lyceon_json$[{"key":"A","text":"halted by preventing further movement or development"},{"key":"B","text":"captured by legal authorities for criminal offenses"},{"key":"C","text":"recorded in detailed written documentation for posterity"},{"key":"D","text":"accelerated beyond the capacity for effective management"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes railway expansion severing migration routes and compelling communities to adopt fixed settlements, indicating that seasonal migration patterns were halted by preventing further movement or development. The option about capture by legal authorities for criminal offenses refers to the law-enforcement sense of "arrested," which has no relevance to migration patterns being disrupted by infrastructure. The option about recording in detailed documentation introduces an archival meaning that is unrelated to the passage''s discussion of physical disruption of movement. The option about acceleration contradicts the passage, which describes migration being stopped, not sped up.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N8XGW0', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly challenge the mechanism proposed by Vasquez and Inoue?', E'Geophysicists Maria Vasquez and Kenji Inoue analyzed seismic wave attenuation data from 31 recording stations surrounding the Toba caldera in Sumatra. They found that seismic waves passing beneath the caldera''s eastern rim lost significantly more energy than waves passing beneath the western rim at comparable depths. Vasquez and Inoue proposed that a pocket of partially molten rock, roughly 4 kilometers in diameter, persists beneath the eastern rim and absorbs seismic energy through viscous dissipation. They argued that this melt pocket is sustained by a localized upwelling of mantle material along a deep-seated fault that intersects the caldera''s eastern boundary. The researchers further noted that this asymmetric melt distribution could explain why historical eruptions at Toba have preferentially vented through the caldera''s eastern flank.', $lyceon_json$[{"key":"A","text":"High-resolution magnetotelluric surveys reveal no detectable zone of elevated electrical conductivity beneath the eastern rim at depths consistent with partially molten rock, despite detecting such zones beneath other active calderas using identical instrumentation and survey protocols."},{"key":"B","text":"Seismic stations on the eastern rim of Toba caldera are situated on thicker unconsolidated volcanic ash deposits than stations on the western rim, and unconsolidated sediments are known to attenuate seismic waves independently of subsurface melt conditions."},{"key":"C","text":"Satellite-based interferometric measurements show that the eastern rim of Toba caldera is subsiding at a rate of 2.7 millimeters per year, consistent with the cooling and contraction of a subsurface magma body beneath that portion of the caldera."},{"key":"D","text":"Geochemical analysis of gas emissions from fumaroles on Toba's eastern flank reveals elevated concentrations of sulfur dioxide and hydrogen sulfide, gases typically associated with degassing from shallow magmatic sources beneath volcanic structures."}]$lyceon_json$::jsonb, 'B', NULL, E'Vasquez and Inoue attribute the asymmetric seismic attenuation to a partially molten rock pocket beneath the eastern rim. A finding that eastern-rim stations sit on thicker unconsolidated ash, which independently attenuates seismic waves, would provide an alternative surface-layer explanation for the observed energy loss, directly challenging the need to invoke a subsurface melt pocket. The magnetotelluric survey finding is relevant but addresses the melt pocket''s existence rather than the specific mechanism of viscous dissipation; furthermore, absence of conductivity anomalies at one caldera does not rule out the mechanism as firmly as a competing cause for the same observation does. The subsidence measurement would actually support the presence of a cooling magma body beneath the eastern rim, reinforcing rather than undermining the proposal. The fumarole gas emissions similarly support the presence of shallow magmatic material, consistent with the proposed mechanism rather than contradicting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NHT1Z3', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, how does the finding described in Text 2 relate to the argument presented in Text 1?', E'Text 1: Urban planner Josephine Achebe argues that the decline of independent bookshops in Lagos since 2015 reflects a broader failure of municipal zoning policy. According to Achebe, commercial rent deregulation has allowed landlords in high-traffic districts to price out culturally significant small businesses in favor of multinational retail chains. She maintains that without zoning protections, market forces will systematically eliminate the independent retail establishments that give neighborhoods their distinctive character.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q1PPOM', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'Geochemist Elif Korkmaz has proposed that the basaltic formations along Turkey''s Hatay coastline were not produced by a single volcanic episode, as conventional models suggest, but by at least three distinct magmatic pulses separated by intervals of marine sedimentation. Her team''s zircon dating of 53 core samples yielded crystallization ages clustering around 91, 84, and 77 million years ago, with interbedded limestone layers between each cluster. <u>Critics point out that zircon crystals can be reworked by erosion and redeposited in younger strata, potentially creating the illusion of discrete age clusters where continuous volcanism actually occurred.</u> Korkmaz counters that the chemical composition of the zircons in each cluster differs markedly, with distinct hafnium-to-zirconium ratios that would not survive the homogenizing effects of sedimentary reworking.', $lyceon_json$[{"key":"A","text":"It introduces an objection to Korkmaz's methodology that the final sentence then addresses with additional geochemical evidence"},{"key":"B","text":"It provides corroborating evidence from an independent research team that strengthens Korkmaz's multi-pulse hypothesis"},{"key":"C","text":"It summarizes the conventional volcanic model that Korkmaz's research was originally designed to confirm"},{"key":"D","text":"It identifies a flaw in the dating technique that Korkmaz ultimately concedes undermines her original interpretation of the data"}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence presents critics'' objection that zircon reworking could create an illusion of discrete age clusters, and the following sentence shows Korkmaz countering with evidence about distinct hafnium-to-zirconium ratios. This makes the underlined sentence an objection that the final sentence then addresses. The option about providing corroborating evidence is wrong because the critics challenge rather than support Korkmaz''s hypothesis. The option about summarizing the conventional model is wrong because the conventional single-episode model was introduced in the first sentence; the underlined sentence raises a specific methodological concern about zircon reliability, not a restatement of the conventional view. The option about Korkmaz conceding a flaw is wrong because the passage shows Korkmaz rebutting the criticism with chemical composition data, not accepting it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SFQU2O', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Entomologist Clara Muriithi and her team at the Kenya Agricultural Research Institute spent three years monitoring the pollination behavior of stingless bees in 46 smallholder mango orchards across Machakos County. Their 2023 report found that orchards within 200 meters of intact scrubland harbored four times as many stingless bee colonies as orchards surrounded entirely by cropland. Fruit set in the scrubland-adjacent orchards was 38 percent higher. Muriithi concluded that preserving patches of native vegetation near mango orchards sustains stingless bee populations and substantially improves mango yields.', $lyceon_json$[{"key":"A","text":"Stingless bees are the only pollinator species capable of successfully pollinating mango blossoms in the climatic conditions found across Machakos County."},{"key":"B","text":"Maintaining native scrubland near mango orchards supports stingless bee colonies and meaningfully increases fruit production."},{"key":"C","text":"Kenya's agricultural policy should mandate buffer zones of at least 200 meters of scrubland around all commercial fruit orchards in semi-arid regions."},{"key":"D","text":"Smallholder mango farmers in Machakos County have historically cleared native scrubland to expand their orchards, reducing biodiversity and pollination rates over several decades."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on Muriithi''s conclusion that preserving native vegetation near mango orchards sustains stingless bee populations and improves yields. The option about maintaining scrubland and increasing fruit production directly captures this finding. The option claiming stingless bees are the only capable pollinator overstates the passage, which discusses stingless bee abundance but never excludes other pollinators. The option about mandating buffer zones introduces a policy recommendation the passage does not make. The option about historical clearing practices introduces background the passage never addresses; the study compares orchard proximity to scrubland, not land-use changes over time.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V33W8N', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The Atacama Desert in Chile receives less than 15 millimeters of rainfall per year, making it one of the driest places on Earth. ______ microbiologists have discovered thriving colonies of extremophilic bacteria beneath the desert''s salt crusts, sustained by trace moisture absorbed from coastal fog.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Yet"},{"key":"D","text":"In summary,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage sets up an expectation that extreme dryness would preclude life, then reveals that bacteria nevertheless thrive there. "Yet" correctly signals this surprising contrast. "For instance," incorrectly treats the bacterial discovery as an example of the desert''s dryness. "Consequently," wrongly implies the bacteria are a result of the low rainfall. "In summary," incorrectly frames the second sentence as a summation of the first when it actually introduces new, contrasting information.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VM34CX', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Linguist Fatima el-Rashid documented that speakers of Darija, the colloquial Arabic of Morocco, frequently incorporate French loanwords into everyday conversation, a phenomenon she attributes to colonial-era education policies. El-Rashid''s corpus analysis of 8,200 recorded conversations showed that French loanwords appear in 41 percent of utterances about technology and commerce. ______ el-Rashid emphasizes that these borrowings do not signal a weakening of Darija''s grammatical structure: the loanwords are systematically adapted to Arabic morphological patterns, receiving Arabic pluralization, verb conjugation, and phonological modification.', $lyceon_json$[{"key":"A","text":"Crucially, though,"},{"key":"B","text":"Along these lines,"},{"key":"C","text":"To put it another way,"},{"key":"D","text":"This is because"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first establishes that French loanwords are pervasive in Darija, which could suggest linguistic erosion. The sentence after the blank counters this implication by arguing that the borrowings are structurally integrated, not destructive. "Crucially, though," both signals the importance of the clarification and introduces the concessive turn. "Along these lines," wrongly implies the structural-integrity claim continues the same line of reasoning as the borrowing frequency, when it actually reframes the reader''s interpretation. "To put it another way," incorrectly presents the structural argument as a restatement of the frequency data rather than a qualification of its implications. "This is because" treats the structural adaptation as the cause of the high borrowing rate, reversing the logical relationship el-Rashid draws.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W2VLT9', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 2017, marine archaeologist Dario Quintero recovered fragments of a seventeenth-century Portuguese merchant vessel from the seabed near Mozambique. Although the wooden hull had largely disintegrated, Quintero found that the copper sheathing on the vessel''s underside ______ remarkably intact, preserving tool marks that revealed details about shipbuilding techniques used in Lisbon''s royal dockyards.', $lyceon_json$[{"key":"A","text":"has remained"},{"key":"B","text":"had remained"},{"key":"C","text":"would remain"},{"key":"D","text":"is remaining"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence describes what Quintero found in 2017: the copper sheathing had stayed intact over the centuries up to the point of his discovery. The past perfect "had remained" correctly indicates a state that persisted up to another past event (the 2017 recovery). The present perfect "has remained" incorrectly links the action to the present moment rather than situating it relative to the past discovery. The conditional "would remain" implies a hypothetical or predicted outcome rather than an observed fact. The present progressive "is remaining" places the action in the present tense, which conflicts with the past-tense narrative established by "recovered" and "found."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W8HMWH', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Nutritionist Harpreet Bains argues that school breakfast programs in British Columbia have substantially improved student concentration during morning classes. Her 2020 study of 1,150 students across fourteen elementary schools found that daily attendance at a free breakfast program correlated with a 29 percent reduction in teacher-reported attention lapses before noon.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W9I3UH', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Most accounts of the Bauhaus school''s dissolution in 1933 emphasize political pressure from the Nazi regime as the decisive factor. However, architectural historian Miriam Strauss has documented severe internal disputes over curriculum reform that predated the political crisis by nearly two years. Faculty meeting minutes from 1931 reveal that instructors were deeply divided over whether the school should prioritize industrial design partnerships or maintain its commitment to experimental fine arts. Strauss argues that these institutional fractures had already weakened the Bauhaus''s organizational coherence, making it far more vulnerable to external political threats than a unified institution would have been.', $lyceon_json$[{"key":"A","text":"It presents a dominant historical narrative, introduces archival evidence that complicates it, and offers an interpretation linking internal and external causes of an institution's collapse"},{"key":"B","text":"It compares two artistic philosophies within a single school, evaluates the strengths of each philosophy, and explains why one ultimately prevailed over the other"},{"key":"C","text":"It describes the founding of a cultural institution, traces the growth of its international reputation, and then accounts for its sudden decline in influence"},{"key":"D","text":"It summarizes an art historian's original argument, presents documentary evidence that refutes that argument, and proposes a replacement theory based on newly available sources"}]$lyceon_json$::jsonb, 'A', NULL, E'The text opens with the dominant account (Nazi political pressure as the decisive cause), introduces archival evidence of internal faculty disputes that predated the political crisis, and then presents Strauss''s interpretation that institutional fractures made the school more vulnerable to external threats. The option about comparing two artistic philosophies and explaining why one prevailed is wrong because the text mentions the curriculum dispute to illustrate internal division, not to evaluate which philosophy was superior. The option about tracing an institution from founding through decline is wrong because the text does not discuss the Bauhaus''s founding or growth; it focuses exclusively on the period surrounding its dissolution. The option about presenting and then refuting a historian''s argument is wrong because Strauss''s argument is the one being advanced, not refuted; the archival evidence supports her position rather than undermining it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XV91WE', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Paleobotanist Ingrid Solheim spent three years cataloging fossilized pollen grains extracted from sediment cores in northern ______ analysis revealed that seven previously unidentified plant species had thrived in the region during the late Miocene epoch.', $lyceon_json$[{"key":"A","text":"Norway, her"},{"key":"B","text":"Norway; her"},{"key":"C","text":"Norway her"},{"key":"D","text":"Norway, consequently, her"}]$lyceon_json$::jsonb, 'B', NULL, E'The blank separates two independent clauses: one about Solheim cataloging fossilized pollen grains and one about what her analysis revealed. A semicolon correctly joins two closely related independent clauses. Using only a comma after "Norway" before "her" creates a comma splice, because both clauses are independent and a comma alone cannot join them. Omitting all punctuation after "Norway" produces a run-on sentence that fuses two independent clauses together. Using commas around "consequently" after "Norway" also creates a comma splice, since "consequently" is a conjunctive adverb and requires a semicolon or period before it, not merely a comma, when it joins independent clauses.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YE29O4', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Based on the text, what can most reasonably be inferred about the weaverbird nests described in the study?', E'Behavioral ecologist Samuel Odhiambo observed that male village weaverbirds in western Kenya construct an average of 5 nests per breeding season, but females typically accept fewer than 2 of those nests for egg laying. Odhiambo found that rejected nests consistently had entrance tunnels shorter than 9 centimeters, whereas accepted nests had tunnels averaging 14 centimeters. He noted that longer entrance tunnels make it more difficult for egg-eating snakes to reach the nest chamber, and females appeared to evaluate tunnel length by entering and exiting each nest multiple times before making a selection.', $lyceon_json$[{"key":"A","text":"The majority of nests built by male weaverbirds fail to meet the structural standard that females use when selecting a site for egg laying."},{"key":"B","text":"Female weaverbirds in western Kenya prefer nests built from specific plant fibers that are more resistant to degradation during the rainy season."},{"key":"C","text":"Male weaverbirds construct multiple nests primarily to attract several different females simultaneously during a single breeding season."},{"key":"D","text":"Egg-eating snakes are responsible for the majority of weaverbird egg losses in western Kenya, making predator defense the most critical factor in nest construction across all bird species in the region."}]$lyceon_json$::jsonb, 'A', NULL, E'Males build an average of 5 nests but females accept fewer than 2, meaning more than half of all nests are rejected. One can reasonably infer that the majority of nests fail to meet the female''s selection standard. The option about plant fiber preferences introduces material the passage never discusses. The option about attracting multiple females proposes a motive not addressed in the passage, which focuses on female choice rather than male mating strategy. The option about snakes causing the majority of egg losses and tunnel length being the most critical factor across all species generalizes far beyond the passage, which discusses one species and does not quantify predation losses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YEEZ83', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Sociologist Amara Diallo conducted a five-year longitudinal study examining civic engagement among first-generation immigrants in Lyon, France. Diallo found that participants who had joined neighborhood associations within their first year of residency ______ volunteering at twice the rate of those who had not, a disparity that persisted even after she controlled for differences in income, education, and employment status.', $lyceon_json$[{"key":"A","text":"continued"},{"key":"B","text":"had been continuing"},{"key":"C","text":"will have continued"},{"key":"D","text":"have been continuing"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence reports Diallo''s finding from her completed study. The verb in the "that" clause following "found" should be in the simple past to describe what was true at the time of the study''s observation: participants "continued" volunteering at a higher rate. The past perfect progressive "had been continuing" would place the action further back in time than the finding itself, creating an unnecessary and illogical additional layer of past reference when the simple past already matches the narrative timeline. The future perfect "will have continued" shifts the tense forward, which is inconsistent with a study that has already concluded. The present perfect progressive "have been continuing" links the action to the present, conflicting with the past-tense frame of "Diallo found." The difficulty lies in recognizing that a reported finding within a past-tense narrative calls for simple past rather than any progressive or perfect construction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
